// Zed extension glue for DartNative, written in C so it can be built with
// wasi-sdk alone (no Rust toolchain). It does the same job as src/lib.rs:
// write the embedded language server into the extension's work directory and
// tell Zed to run it with Zed's Node.js.
//
// Build: wasm/build.sh (needs wasi-sdk, wit-bindgen and wasm-tools).

#include <dirent.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include "extension.h"
#include "embedded.h"  // SERVER_JS / API_INDEX_JSON byte arrays, generated by build.sh

#define SERVER_DIR "dartnative-lsp-" EXTENSION_VERSION
#define SETTINGS_KEY "dartnative"

// The `zed:api-version` custom section (API 0.7.0) is appended by build.sh.

static bool fail(extension_string_t *err, const char *msg) {
  extension_string_dup(err, msg);
  return false;
}

static bool fail_errno(extension_string_t *err, const char *what, const char *path) {
  char buf[512];
  snprintf(buf, sizeof buf, "dartnative: %s %s: %s", what, path, strerror(errno));
  return fail(err, buf);
}

static bool same_contents(const char *path, const unsigned char *data, size_t len) {
  FILE *f = fopen(path, "rb");
  if (!f) return false;
  bool same = true;
  unsigned char buf[8192];
  size_t off = 0, n;
  while ((n = fread(buf, 1, sizeof buf, f)) > 0) {
    if (off + n > len || memcmp(buf, data + off, n) != 0) { same = false; break; }
    off += n;
  }
  fclose(f);
  return same && off == len;
}

static bool write_if_changed(const char *path, const unsigned char *data, size_t len, extension_string_t *err) {
  if (same_contents(path, data, len)) return true;
  FILE *f = fopen(path, "wb");
  if (!f) return fail_errno(err, "cannot write", path);
  bool ok = fwrite(data, 1, len, f) == len;
  ok = (fclose(f) == 0) && ok;
  if (!ok) return fail_errno(err, "cannot write", path);
  return true;
}

// Remove server folders left behind by older versions of this extension.
static void remove_stale_servers(void) {
  DIR *d = opendir(".");
  if (!d) return;
  struct dirent *e;
  char path[1024];
  while ((e = readdir(d)) != NULL) {
    if (strncmp(e->d_name, "dartnative-lsp-", 15) != 0 || strcmp(e->d_name, SERVER_DIR) == 0) continue;
    snprintf(path, sizeof path, "%s/dartnative-lsp.js", e->d_name);
    unlink(path);
    snprintf(path, sizeof path, "%s/dartnative-api.json", e->d_name);
    unlink(path);
    rmdir(e->d_name);
  }
  closedir(d);
}

static bool ensure_server_files(extension_string_t *err) {
  if (mkdir(SERVER_DIR, 0755) != 0 && errno != EEXIST) return fail_errno(err, "cannot create", SERVER_DIR);
  if (!write_if_changed(SERVER_DIR "/dartnative-lsp.js", SERVER_JS, SERVER_JS_LEN, err)) return false;
  if (!write_if_changed(SERVER_DIR "/dartnative-api.json", API_INDEX_JSON, API_INDEX_JSON_LEN, err)) return false;
  remove_stale_servers();
  return true;
}

void exports_extension_init_extension(void) {}

bool exports_extension_language_server_command(extension_string_t *language_server_id,
                                               extension_borrow_worktree_t worktree,
                                               extension_command_t *ret, extension_string_t *err) {
  extension_string_free(language_server_id);

  // Read what we need from the lent worktree handle, then give it back right
  // away: the component model requires every borrowed handle to be released
  // before the call returns, on every path.
  uint64_t worktree_id = extension_method_worktree_id(worktree);
  extension_worktree_drop_borrow(worktree);

  if (!ensure_server_files(err)) return false;

  // Zed sets PWD to the extension's work directory on the host.
  const char *pwd = getenv("PWD");
  if (!pwd || !*pwd) return fail(err, "dartnative: work directory (PWD) is not set");

  extension_string_t node, node_err;
  if (!zed_extension_nodejs_node_binary_path(&node, &node_err)) {
    *err = node_err;
    return false;
  }

  // The user's `lsp.dartnative` settings (JSON). The server reads
  // initialization_options from it, so no JSON parsing is needed here.
  extension_settings_location_t loc;
  loc.worktree_id = worktree_id;
  extension_string_set(&loc.path, "");
  extension_string_t category, key, settings_json, settings_err;
  extension_string_set(&category, "lsp");
  extension_string_set(&key, SETTINGS_KEY);
  bool have_settings = extension_get_settings(&loc, &category, &key, &settings_json, &settings_err);
  if (!have_settings) extension_string_free(&settings_err);

  size_t script_len = strlen(pwd) + 1 + strlen(SERVER_DIR) + strlen("/dartnative-lsp.js") + 1;
  char *script = malloc(script_len);
  snprintf(script, script_len, "%s/%s/dartnative-lsp.js", pwd, SERVER_DIR);

  ret->command = node;
  ret->args.len = 1;
  ret->args.ptr = malloc(sizeof(extension_string_t));
  ret->args.ptr[0].ptr = (uint8_t *)script;
  ret->args.ptr[0].len = strlen(script);

  if (have_settings) {
    ret->env.len = 1;
    ret->env.ptr = malloc(sizeof(extension_tuple2_string_string_t));
    extension_string_dup(&ret->env.ptr[0].f0, "DARTNATIVE_LSP_SETTINGS");
    ret->env.ptr[0].f1 = settings_json;
  } else {
    ret->env.len = 0;
    ret->env.ptr = NULL;
  }
  return true;
}

static bool no_string(extension_option_string_t *ret) {
  ret->is_some = false;
  return true;
}

bool exports_extension_language_server_initialization_options(extension_string_t *id, extension_borrow_worktree_t w,
                                                              extension_option_string_t *ret, extension_string_t *err) {
  (void)err;
  extension_worktree_drop_borrow(w);
  extension_string_free(id);
  return no_string(ret);
}

