// No custom labels: answer "none" for each item so Zed uses its defaults.
static void no_labels(size_t n, extension_list_option_code_label_t *ret) {
  ret->len = n;
  ret->ptr = n ? calloc(n, sizeof(extension_option_code_label_t)) : NULL;
}

bool exports_extension_labels_for_completions(extension_string_t *id, extension_list_completion_t *completions,
                                              extension_list_option_code_label_t *ret, extension_string_t *err) {
  (void)err;
  no_labels(completions->len, ret);
  extension_string_free(id);
  extension_list_completion_free(completions);
  return true;
}

bool exports_extension_labels_for_symbols(extension_string_t *id, extension_list_symbol_t *symbols,
                                          extension_list_option_code_label_t *ret, extension_string_t *err) {
  (void)err;
  no_labels(symbols->len, ret);
  extension_string_free(id);
  extension_list_symbol_free(symbols);
  return true;
}

// Everything below is unused by this extension (slash commands, context
// servers, docs, debuggers) and reports "not supported".

#define UNSUPPORTED "not supported by the DartNative extension"

bool exports_extension_complete_slash_command_argument(extension_slash_command_t *command, extension_list_string_t *args,
                                                       extension_list_slash_command_argument_completion_t *ret,
                                                       extension_string_t *err) {
  (void)ret;
  extension_slash_command_free(command);
  extension_list_string_free(args);
  return fail(err, UNSUPPORTED);
}

bool exports_extension_run_slash_command(extension_slash_command_t *command, extension_list_string_t *args,
                                         extension_borrow_worktree_t *maybe_worktree, extension_slash_command_output_t *ret,
                                         extension_string_t *err) {
  (void)ret;
  if (maybe_worktree) extension_worktree_drop_borrow(*maybe_worktree);
  extension_slash_command_free(command);
  extension_list_string_free(args);
  return fail(err, UNSUPPORTED);
}

